def average(values):
    return sum(values) / len(values)

try:
    average([])
except ZeroDivisionError as error:
    print(type(error).__name__)

def first_even(values):
    for value in values:
        if value % 2 == 0:
            return value
    return None

assert first_even([1, 3, 4]) == 4

